mapper.select:
SELECT * FROM req_requirement

    region = #{region}
    status = #{status}
    task_name LIKE CONCAT('%',#{taskName},'%')

SELECT * FROM req_requirement


        region = #{region}


        status = #{status}


        task_name LIKE CONCAT('%',#{taskName},'%')

SELECT * FROM req_requirement
ORDER BY create_time DESC
LIMIT #{limit}

SELECT region, tech_manager, dev_manager, dev_leader, test_leader, task_name, trigger_item, conclusion, deadline, status, remark FROM req_requirement
region = #{region}
status = #{status}
task_name LIKE CONCAT('%',#{taskName},'%')

SELECT
${groupField} AS groupName,
COUNT(*) AS total,
SUM(CASE WHEN conclusion = '测试团队介入保障' THEN 1 ELSE 0 END) AS testJoin,
SUM(CASE WHEN conclusion = '研发自测负责' THEN 1 ELSE 0 END) AS devSelf,
GROUP_CONCAT(DISTINCT
CASE
WHEN trigger_item LIKE '%：%' THEN SUBSTRING_INDEX(trigger_item, '：', 1)
WHEN trigger_item LIKE '%:%' THEN SUBSTRING_INDEX(trigger_item, ':', 1)
WHEN trigger_item LIKE '% %' THEN SUBSTRING_INDEX(trigger_item, ' ', 1)
ELSE trigger_item
END
) AS triggerItems
FROM req_requirement

    1=1

        DATE(create_time) >= #{startDate}


        DATE(create_time) <= #{endDate}


        AND region = #{region}


        AND conclusion = #{conclusion}


GROUP BY ${groupField}
